            <ResultList
              results={results}
              activeIndex={activeIndexInRange}
              onActivate={setActiveIndex}
            />
          )}
        </div>
        <PreviewPane app={app} result={activeResult} authorName={authorName} />
      </div>
      <NodeSearchFooter
        canAct={nodesState.status === "ready" && !!activeResult}
        canInsertLink={!!insertTarget}
        isActiveResultLinkable={isActiveResultLinkable}
        onClose={onClose}
        onInsertLink={insertLinkToActiveResult}
        onOpenInNewTab={() => openActiveResult(openFileInNewTab)}
        onOpenInSplit={() => openActiveResult(openFileInNewLeaf)}
      />
    </div>
  );
};

export class NodeSearchModal extends Modal {
  private plugin: DiscourseGraphPlugin;
  private root: Root | null = null;
  /** Snapshotted in the constructor: `open()` has not taken focus yet. */
  private insertTarget: EditorInsertTarget | null;

  constructor(app: App, plugin: DiscourseGraphPlugin) {
    super(app);
    this.plugin = plugin;
    this.insertTarget = snapshotInsertTarget(app);
  }

  onOpen() {
    const { contentEl, modalEl } = this;
    // The default modal is too narrow for a result list beside a preview pane.
    // Responsive layout is an explicit non-goal, so this is a desktop-only size.
    modalEl.addClasses([
      "dg-node-search-modal",
      "h-[600px]",
      "max-h-[80vh]",
      "w-[900px]",
      "max-w-[90vw]",
    ]);
    contentEl.addClasses(["flex", "h-full", "flex-col", "overflow-hidden"]);
    contentEl.empty();
    this.root = createRoot(contentEl);
    this.root.render(
      <StrictMode>
        <NodeSearch
          plugin={this.plugin}
          insertTarget={this.insertTarget}
          onClose={() => this.close()}
        />
      </StrictMode>,
    );
  }

  onClose() {
    if (this.root) {
      this.root.unmount();
      this.root = null;
    }
    this.contentEl.empty();
  }
}

import { Platform } from "obsidian";
import type { KeyboardEvent } from "react";

export type HintKey = "Mod" | "Alt" | "Shift" | "Enter" | "Escape" | "Tab";

// Obsidian shows glyphs on macOS and spelled-out words everywhere else.
const MAC_SYMBOLS: Record<HintKey, string> = {
  Mod: "⌘",
  Alt: "⌥",
  Shift: "⇧",
  Enter: "↵",
  Escape: "esc",
  Tab: "⇥",
};

const NON_MAC_SYMBOLS: Record<HintKey, string> = {
  Mod: "Ctrl",
  Alt: "Alt",
  Shift: "Shift",
  Enter: "Enter",
  Escape: "Esc",
  Tab: "Tab",
};

/** Takes `isMacOS` so the non-mac branch can be checked without that platform. */
export const formatHintKeys = ({
  keys,
  isMacOS,
}: {
  keys: HintKey[];
  isMacOS: boolean;
}): string[] =>
  keys.map((key) => (isMacOS ? MAC_SYMBOLS : NON_MAC_SYMBOLS)[key]);

export const getHintKeys = (keys: HintKey[]): string[] =>
  formatHintKeys({ keys, isMacOS: Platform.isMacOS });

// Rows are divs, so Enter and Space have to be wired up the way a button gets them free.
export const activateOnKey = (
  event: KeyboardEvent<HTMLDivElement>,
  activate: () => void,
): void => {
  if (event.key !== "Enter" && event.key !== " ") return;
  event.preventDefault();
  activate();
};
