// ENG-2265 preview toggle in Advanced Node Search.
const MODAL = ".dg-node-search-modal";
const INPUT = `${MODAL} [role="textbox"]`;
const LIST = `${MODAL} [role="listbox"]`;
const OPTION = `${MODAL} [role="option"]`;

const K = {
  left: { key: "ArrowLeft", code: "ArrowLeft", windowsVirtualKeyCode: 37, nativeVirtualKeyCode: 37 },
  right: { key: "ArrowRight", code: "ArrowRight", windowsVirtualKeyCode: 39, nativeVirtualKeyCode: 39 },
  down: { key: "ArrowDown", code: "ArrowDown", windowsVirtualKeyCode: 40, nativeVirtualKeyCode: 40 },
  tab: { key: "Tab", code: "Tab", windowsVirtualKeyCode: 9, nativeVirtualKeyCode: 9 },
};

const openSearch = async ({ client, json, vault }) => {
  await client.evaluate(`return app.commands.executeCommandById(${json(`${vault.pluginId}:open-node-search`)});`);
  await client.waitFor(`!!document.querySelector(${json(OPTION)})`, { label: "results rendered" });
};

const click = async ({ client }, selectorExpr) => {
  const { x, y } = await client.evaluate(`const r = (${selectorExpr}).getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };`);
  for (const type of ["mouseMoved", "mousePressed", "mouseReleased"]) {
    await client.send("Input.dispatchMouseEvent", { type, x, y, button: "left", clickCount: 1 });
  }
};

const footerButton = (json, label) =>
  `Array.from(document.querySelectorAll(${json(`${MODAL} .dg-search-footer-action`)}))
    .find((b) => b.textContent.trim().endsWith(${json(label)}) && !b.textContent.includes("close preview") === (${json(label)} === "preview"))`;

const state = ({ client, json }) =>
  client.evaluate(`const list = document.querySelector(${json(LIST)});
    const column = list.parentElement, box = column.parentElement;
    const cs = getComputedStyle(column);
    const preview = column.nextElementSibling;
    const active = document.activeElement;
    return {
      previewOpen: box.children.length === 2,
      columnRatio: +(column.getBoundingClientRect().width / box.getBoundingClientRect().width).toFixed(2),
      divider: cs.borderRightStyle + " " + cs.borderRightWidth,
      previewTitle: preview?.querySelector(".font-semibold")?.textContent ?? null,
      focus: active === list ? "list" : active?.getAttribute("role") ?? active?.tagName,
      footer: Array.from(document.querySelectorAll(${json(`${MODAL} .dg-search-footer-action`)})).map((b) => b.textContent.trim()),
      query: document.querySelector(${json(INPUT)}).textContent,
    };`);

const clickFirstRow = (ctx) => click(ctx, `document.querySelector(${ctx.json(OPTION)})`);

export default [
  {
    name: "Preview hidden on open",
    input: "open node search",
    expected: "no preview, list full width, footer shows '→ preview'",
    run: async (ctx) => {
      await openSearch(ctx);
      return state(ctx);
    },
    expect: (s) => ({
      pass: !s.previewOpen && s.columnRatio > 0.95 && s.footer.some((l) => l.endsWith("preview") && l.includes("→")),
      actual: `open=${s.previewOpen}, list ${s.columnRatio * 100}% wide, footer: ${s.footer.join(" / ")}`,
    }),
  },
  {
    name: "Arrows in query move caret only",
    input: "focus query, type 'ab', ←, then → → (caret at end)",
    expected: "caret moves 2→1→2, preview stays closed",
    run: async (ctx) => {
      const { client, json } = ctx;
      await openSearch(ctx);
      await client.evaluate(`document.querySelector(${json(INPUT)}).focus(); return true;`);
      await client.typeText("ab");
      const caret = () => client.evaluate(`return getSelection().anchorOffset;`);
      const offsets = [await caret()];
      await client.key(K.left);
      offsets.push(await caret());
      await client.key(K.right);
      await client.key(K.right);
      offsets.push(await caret());
      return { offsets, ...(await state(ctx)) };
    },
    expect: (s) => ({
      pass: s.offsets.join() === "2,1,2" && !s.previewOpen && s.focus === "textbox",
      actual: `caret ${s.offsets.join("→")}, open=${s.previewOpen}, focus=${s.focus}`,
    }),
  },
  {
    name: "Click row then → opens preview",
    input: "click first result, →, ↓",
    expected: "list focused; preview opens with divider; ↓ updates preview; footer '← close preview'",
    run: async (ctx) => {
      const { client } = ctx;
      await openSearch(ctx);
      await clickFirstRow(ctx);
      await client.key(K.right);
      await client.waitFor(`!!document.querySelector(".dg-node-search-modal [role=listbox]").parentElement.nextElementSibling`, { label: "preview open" });
      const first = await state(ctx);
      await client.key(K.down);
      await new Promise((r) => setTimeout(r, 300));
      const second = await state(ctx);
      return { first, second };
    },
    expect: ({ first, second }) => ({
      pass:
        first.focus === "list" && first.previewOpen && first.divider === "solid 1px" &&
        first.columnRatio < 0.5 && first.footer.some((l) => l.endsWith("close preview")) &&
        second.previewOpen && second.previewTitle !== first.previewTitle,
      actual: `focus=${first.focus}, divider=${first.divider}, list ${first.columnRatio * 100}%, preview "${first.previewTitle}" → "${second.previewTitle}"`,
    }),
  },
  {
    name: "← in list closes preview",
    input: "click first result, →, ←",
    expected: "preview closes, list back to full width, focus stays on list",
    run: async (ctx) => {
      const { client } = ctx;
      await openSearch(ctx);
      await clickFirstRow(ctx);
      await client.key(K.right);
      await client.key(K.left);
      return state(ctx);
    },
    expect: (s) => ({
      pass: !s.previewOpen && s.columnRatio > 0.95 && s.focus === "list",
      actual: `open=${s.previewOpen}, list ${s.columnRatio * 100}%, focus=${s.focus}`,
    }),
  },
  {
    name: "Typing in list returns to query",
    input: "focus query, type 'a'; click first result; type 'b'",
    expected: "focus back in query, query 'ab'",
    run: async (ctx) => {
      const { client, json } = ctx;
      await openSearch(ctx);
      await client.evaluate(`document.querySelector(${json(INPUT)}).focus(); return true;`);
      await client.typeText("a");
      await client.waitFor(`!!document.querySelector(${json(OPTION)})`, { label: "results after a" });
      await new Promise((r) => setTimeout(r, 400));
      await clickFirstRow(ctx);
      const before = (await state(ctx)).focus;
      await client.typeText("b");
      return { before, ...(await state(ctx)) };
    },
    expect: (s) => ({
      pass: s.before === "list" && s.focus === "textbox" && s.query === "ab",
      actual: `focus ${s.before}→${s.focus}, query "${s.query}"`,
    }),
  },
  {
    name: "Footer button toggles preview",
    input: "focus query; click '→ preview'; click '← close preview'",
    expected: "opens then closes; focus stays in query",
    run: async (ctx) => {
      const { client, json } = ctx;
      await openSearch(ctx);
      await client.evaluate(`document.querySelector(${json(INPUT)}).focus(); return true;`);
      await click(ctx, footerButton(json, "preview"));
      const opened = await state(ctx);
      await click(ctx, footerButton(json, "close preview"));
      return { opened, closed: await state(ctx) };
    },
    expect: ({ opened, closed }) => ({
      pass: opened.previewOpen && !closed.previewOpen && opened.focus === "textbox" && closed.focus === "textbox",
      actual: `open=${opened.previewOpen}→${closed.previewOpen}, focus ${opened.focus}/${closed.focus}`,
    }),
  },
  {
    name: "← at query start still focuses chip",
    input: "type first node type name, Tab to commit chip, ←",
    expected: "chip focused, preview stays closed",
    run: async (ctx) => {
      const { client, json, vault } = ctx;
      await openSearch(ctx);
      const name = await client.evaluate(`return app.plugins.plugins[${json(vault.pluginId)}].settings.nodeTypes[0].name;`);
      await client.evaluate(`document.querySelector(${json(INPUT)}).focus(); return true;`);
      await client.typeText(name);
      await client.key(K.tab);
      await new Promise((r) => setTimeout(r, 300));
      await client.key(K.left);
      const s = await state(ctx);
      const chip = await client.evaluate(`return document.activeElement?.getAttribute("aria-label");`);
      return { name, chip, ...s };
    },
    expect: (s) => ({
      pass: s.chip === s.name && s.focus === "button" && !s.previewOpen,
      actual: `focused chip "${s.chip}", open=${s.previewOpen}`,
    }),
  },
];

